msg.topic = `
INSERT INTO historico_dinamico (
temperatura, presion_agua, presion_aire, cooler,
nivel, caudal, resistencia, sp_nivel, sp_temp, salida_pid_temperatura,
salida_pid_nivel
) VALUES (?,?,?,?,?,?,?,?,?,?,?)
`;

msg.payload = [
d.Temperatura,
d.PresionAgua,
d.PresionAire,
d.Cooler ? 1 : 0,
d.Nivel,
d.Caudal,
d.Resistencia ? 1 : 0,
d.SP_Nivel,
d.SP_Temp,
d.Salida_PID_temperatura,
d.Salida_PID_Nivel
];

return msg;

let data = msg.payload;

if (!Array.isArray(data)) {
    node.error("La consulta no devolvió un array");
    return null;
}

data.reverse();

let nivel = [];
let spNiv = [];
let salidaPIDNivel = [];

data.forEach((row, i) => {

    let fecha = new Date(row.fecha);

    // Mostrar sólo los primeros 3 registros
    if (i < 3) {
        node.warn({
            fechaOriginal: row.fecha,
            fechaConvertida: fecha,
            timestamp: fecha.getTime()
        });
    }

    nivel.push({
        x: fecha.getTime(),
        y: parseFloat(row.nivel || 0)
    });

    spNiv.push({
        x: fecha.getTime(),
        y: parseFloat(row.sp_nivel || 0)
    });

    salidaPIDNivel.push({
        x: fecha.getTime(),
        y: parseFloat(row.salida_pid_nivel || 0)
    });

});

msg.payload = [{
    series: [
        "Nivel",
        "SP Nivel",
        "Salida PID Nivel"
    ],
    data: [
        nivel,
        spNiv,
        salidaPIDNivel
    ],
    labels: []
}];

return msg;

let data = msg.payload;

