// Convierte timestamp a formato MySQL
function convertirFecha(ts) {

    let d = new Date(Number(ts));

    // Compensar GMT-3
    d.setHours(d.getHours() + 3);

    let anio = d.getFullYear();
    let mes = String(d.getMonth() + 1).padStart(2, "0");
    let dia = String(d.getDate()).padStart(2, "0");

    let hora = String(d.getHours()).padStart(2, "0");
    let min = String(d.getMinutes()).padStart(2, "0");
    let seg = String(d.getSeconds()).padStart(2, "0");

    return `${anio}-${mes}-${dia} ${hora}:${min}:${seg}`;
}

desde = convertirFecha(desde);
hasta = convertirFecha(hasta);

node.warn({
    desde: desde,
    hasta: hasta
});

msg.topic = `
SELECT
    fecha,
    nivel,
    sp_nivel,
    salida_pid_nivel
FROM historico_dinamico
WHERE fecha BETWEEN '${desde}' AND '${hasta}'
ORDER BY fecha ASC
`;

node.warn(msg.topic);

return msg;

if (msg.topic === "desde") {
    flow.set("desde", msg.payload);
    node.warn("Guardado desde: " + msg.payload);
}

if (msg.topic === "hasta") {
    flow.set("hasta", msg.payload);
